registration = prepareCallbackOwner()
token = subscribe(registration.context)
request_stop(token)
result = await_stopped(token)
if result == confirmed:
    release_callback_context(registration)
    destroy_with_provider_releaser(handle)
else:
    cleanupOwner.retainUntilConfirmed(token, registration, handle)
// 超时不释放；此调用只能在允许等待的位置执行

